// Base91 decoding table & constants for compact lossless MIDI storage
const A = "!#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[]^_`abcdefghijklmnopqrstuvwxyz{}~";
const B = A.length; // Radix size (91)
const Z = B - 1; // End-of-varint marker index (90)
const PROGRAM = [65, 59, 33, 0, 56, 56, 115, 12, 36, 0, 37]; // General MIDI program patch presets per channel

// === CABINET_KEYS (DO NOT modify - matches physical cabinet) ===
const CABINET_KEYS = {
  P1_U: ['w'], P1_D: ['s'], P1_L: ['a'], P1_R: ['d'],
  P1_1: ['u'], P1_2: ['i'], P1_3: ['o'],
  P1_4: ['j'], P1_5: ['k'], P1_6: ['l'],
  P2_U: ['ArrowUp'], P2_D: ['ArrowDown'], P2_L: ['ArrowLeft'], P2_R: ['ArrowRight'],
  P2_1: ['r'], P2_2: ['t'], P2_3: ['y'],
  P2_4: ['f'], P2_5: ['g'], P2_6: ['h'],
  START1: ['Enter'], START2: ['2'],
};

const KEY_TO_ARCADE = {};
for (const k in CABINET_KEYS) for (const kk of CABINET_KEYS[k]) KEY_TO_ARCADE[kk.length === 1 ? kk.toLowerCase() : kk] = k;

function getArcadeCode(e) {
  if (!e) return null;
  const k = e.key ? (e.key.length === 1 ? e.key.toLowerCase() : e.key) : '';
  if (KEY_TO_ARCADE[k]) return KEY_TO_ARCADE[k];
  if (e.code) {
    if (KEY_TO_ARCADE[e.code]) return KEY_TO_ARCADE[e.code];
    if (e.code.startsWith('Key')) {
      const ch = e.code.slice(3).toLowerCase();
      if (KEY_TO_ARCADE[ch]) return KEY_TO_ARCADE[ch];
    }
    if (e.code.startsWith('Digit')) {
      const ch = e.code.slice(5);
      if (KEY_TO_ARCADE[ch]) return KEY_TO_ARCADE[ch];
    }
    if (e.code.startsWith('Numpad')) {
      const ch = e.code.slice(6);
      if (KEY_TO_ARCADE[ch]) return KEY_TO_ARCADE[ch];
      if (ch === 'Enter' && KEY_TO_ARCADE['Enter']) return KEY_TO_ARCADE['Enter'];
    }
  }
  return null;
}

const held = Object.create(null);
const justPressed = Object.create(null);
const justReleased = Object.create(null);

function clearInputs() {
  for (const k in held) held[k] = false;
  for (const k in justPressed) justPressed[k] = false;
  for (const k in justReleased) justReleased[k] = false;
}

window.addEventListener('keydown', e => {
  const c = getArcadeCode(e);
  if (c) { if (!held[c]) justPressed[c] = true; held[c] = true; e.preventDefault(); }
});
window.addEventListener('keyup', e => {
  const c = getArcadeCode(e);
  if (c) { held[c] = false; justReleased[c] = true; }
});

const rand = () => Math.random();
const t = (s, c, b) => ({ fontFamily: 'monospace', fontSize: s + 'px', color: c, fontStyle: b ? 'bold' : 'normal' });
const cTxt = (s, x, y, str, sz, c, b) => s.add.text(x, y, str, t(sz, c, b)).setOrigin(.5);
const cRct = (s, x, y, w, h, color, alpha) => s.add.rectangle(x, y, w, h, color, alpha);

